command:
if (!game.user.isGM) return ui.notifications.warn('Promote Unit is GM-only.');

const units = (canvas.tokens?.controlled ?? []).filter(token => token.actor?.type === 'Character');
if (units.length !== 1) return ui.notifications.warn('Select exactly one unit.');

const placed = units[0];
await game.emblemRpg.api.character.classes.openPromotion({
  actorUuid: placed.actor.uuid,
  tokenUuid: placed.document.uuid,
  bypassItem: true,
  bypassRequirements: true
});
